  }
  // 直接量：连续 requestRender 下每帧 wall time 中 JS 部分占比——用 performance.now 采样主线程忙碌度
  const busy = []
  let last = performance.now()
  await new Promise(resolve => {
    const deadline = performance.now() + 4000
    ;(function check() {
      const now = performance.now()
      busy.push(now - last - 16) // 超出 60fps 节拍的部分≈阻塞
      last = now
      if (now < deadline) setTimeout(check, 16); else resolve()
    })()
  })
  const blocked = busy.filter(b => b > 50)
